sys_script.script:
(function executeRule(current, previous /*null when async*/) {
    // Check if transitioning out of Resolved (state 6) back to In Progress (state 2) or New (state 1)
    if (previous.state == '6' && (current.state == '2' || current.state == '1')) {
        if (previous.resolved_at) {
            var resolvedTime = new GlideDateTime(previous.resolved_at).getNumericValue();
            var nowTime = new GlideDateTime().getNumericValue();
            var diffDays = (nowTime - resolvedTime) / (1000 * 60 * 60 * 24);

            if (diffDays <= 3) {
                gs.info("Apollo Network SLA: Incident " + current.number + " reopened within " + diffDays.toFixed(2) + " days (<= 3 days). Flagging SLA reset.");
                // Increment reopen counter or flag to trigger SLA reset condition
                current.reopen_count = (parseInt(current.reopen_count, 10) || 0) + 1;
            } else {
                gs.info("Apollo Network SLA: Incident " + current.number + " reopened after " + diffDays.toFixed(2) + " days (> 3 days). SLA clock will NOT reset.");
            }
        }
    }
})(current, previous);
